package app.multimin.ui;
import javax.swing.*;
import java.awt.*;
import java.nio.file.*;
import java.util.Properties;
import javax.swing.border.EmptyBorder;
import java.awt.Font;
import java.awt.Color;
public final class LegalConsent {
 private static Palette THEME=new Palette();
 private static final String VERSION="2026-11-06-policies";
 private static Color BG=new Color(24,27,33), TEXT=new Color(232,235,240);
 public static void setPalette(Palette palette){THEME=palette;BG=palette.background;TEXT=palette.text;}
 private static JTabbedPane documents(){return PolicyPages.create(THEME,false);}
 public static void showDocuments(Component parent){Window owner=parent==null?null:parent instanceof Window w?w:SwingUtilities.getWindowAncestor(parent);JDialog dialog=new JDialog(owner,"Policies",Dialog.ModalityType.APPLICATION_MODAL);JPanel body=new JPanel(new BorderLayout(12,14));body.setBackground(BG);body.setBorder(new EmptyBorder(16,18,14,18));body.add(documents());JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT,0,0));actions.setOpaque(false);JButton close=new ModernButton("Close",null,THEME,false);close.addActionListener(e->dialog.dispose());actions.add(close);body.add(actions,BorderLayout.SOUTH);dialog.setContentPane(body);dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);dialog.setSize(780,600);dialog.setMinimumSize(new Dimension(600,420));dialog.setLocationRelativeTo(parent);dialog.setVisible(true);}
 public static boolean ensureAccepted(){if(LegalConsent.class.getResource("/legal/TERMS.md")==null || LegalConsent.class.getResource("/legal/PRIVACY.md")==null || LegalConsent.class.getResource("/legal/COOKIE_POLICY.md")==null || LegalConsent.class.getResource("/legal/REFUND_POLICY.md")==null){AppNotice.show(null,THEME,"Agreement unavailable","Agreement documents are missing. Please obtain the complete release.","Close");return false;}Path path=WorkspaceStore.directory().resolve("agreement.properties");Properties p=new Properties();try(var in=Files.newInputStream(path)){p.load(in);if(VERSION.equals(p.getProperty("acceptedVersion")))return true;}catch(Exception ignored){}
  JDialog dialog=new JDialog((Frame)null,"Welcome to MultiMini",true);JPanel body=new JPanel(new BorderLayout(14,14));body.setBackground(BG);body.setBorder(BorderFactory.createEmptyBorder(20,22,18,22));JLabel intro=new JLabel("<html><b>Welcome to MultiMini</b><br>Review the agreement and privacy policy before continuing.</html>");intro.setFont(new Font(Font.DIALOG,Font.PLAIN,14));intro.setForeground(TEXT);body.add(intro,BorderLayout.NORTH);body.add(documents(),BorderLayout.CENTER);JCheckBox agree=new JCheckBox("I have read and agree to the User Agreement and have read the Privacy Policy.");agree.setOpaque(false);agree.setForeground(TEXT);agree.setFont(new Font(Font.DIALOG,Font.PLAIN,12));agree.setIcon(new AccentCheckIcon(THEME));JButton accept=new ModernButton("Agree and continue",null,THEME,true),decline=new ModernButton("Decline and exit",null,THEME,false);accept.setEnabled(false);agree.addActionListener(e->accept.setEnabled(agree.isSelected()));boolean[] result={false};accept.addActionListener(e->{try{Files.createDirectories(path.getParent());Properties record=new Properties();record.setProperty("acceptedVersion",VERSION);record.setProperty("acceptedAt",java.time.Instant.now().toString());try(var out=Files.newOutputStream(path)){record.store(out,"MultiMini local agreement acceptance");}result[0]=true;dialog.dispose();}catch(Exception error){AppNotice.show(dialog,THEME,"Agreement","Could not save acceptance: "+error.getMessage(),"Close");}});decline.addActionListener(e->dialog.dispose());JPanel bottom=new JPanel(new BorderLayout(8,12));bottom.setBackground(BG);bottom.add(agree,BorderLayout.NORTH);JPanel buttons=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));buttons.setOpaque(false);buttons.add(decline);buttons.add(accept);bottom.add(buttons,BorderLayout.SOUTH);body.add(bottom,BorderLayout.SOUTH);dialog.setContentPane(body);dialog.setMinimumSize(new Dimension(620,460));dialog.setSize(780,600);dialog.setResizable(true);dialog.setLocationRelativeTo(null);dialog.setVisible(true);return result[0];
 }
}
